import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;

const apiBaseUrl = String.fromEnvironment('API_BASE_URL', defaultValue: 'http://localhost:8000/api/v1');

class ApiClient {
  String? accessToken;
  Map<String, String> get headers => {'Content-Type': 'application/json', if (accessToken != null) 'Authorization': 'Bearer $accessToken'};
  String error(http.Response r) { try { final d = jsonDecode(r.body); if (d is Map && d['detail'] != null) return d['detail'].toString(); if (d is Map && d.isNotEmpty) { final v = d.values.first; return v is List ? v.first.toString() : v.toString(); } } catch (_) {} return 'خطا در ارتباط با سرور (${r.statusCode})'; }
  Future<void> register(String phone, String password) async { final r = await http.post(Uri.parse('$apiBaseUrl/auth/register/'), headers: headers, body: jsonEncode({'phone': phone, 'password': password})); if (r.statusCode != 201) throw Exception(error(r)); }
  Future<void> login(String phone, String password) async { final r = await http.post(Uri.parse('$apiBaseUrl/auth/token/'), headers: headers, body: jsonEncode({'username': phone, 'password': password})); if (r.statusCode != 200) throw Exception(error(r)); accessToken = jsonDecode(r.body)['access']; }
  Future<List<Map<String, dynamic>>> vehicles() async { final r = await http.get(Uri.parse('$apiBaseUrl/vehicles/'), headers: headers); if (r.statusCode != 200) throw Exception(error(r)); return List<Map<String, dynamic>>.from(jsonDecode(r.body)); }
  Future<Map<String, dynamic>> addVehicle({required String nickname, required String make, required String model, required int year, required int odometer, required String fuelType}) async { final r = await http.post(Uri.parse('$apiBaseUrl/vehicles/'), headers: headers, body: jsonEncode({'nickname': nickname, 'make': make, 'model': model, 'year': year, 'current_odometer_km': odometer, 'fuel_type': fuelType})); if (r.statusCode != 201) throw Exception(error(r)); return Map<String, dynamic>.from(jsonDecode(r.body)); }
}

void main() => runApp(const App());

class App extends StatelessWidget { const App({super.key}); @override Widget build(BuildContext c) => MaterialApp(debugShowCheckedModeBanner: false, title: 'دستیار خودرو', theme: ThemeData(useMaterial3: true, colorScheme: ColorScheme.fromSeed(seedColor: const Color(0xFF10A7A0)), scaffoldBackgroundColor: const Color(0xFFF5F7FA)), home: LoginPage(api: ApiClient())); }

class LoginPage extends StatefulWidget { const LoginPage({super.key, required this.api}); final ApiClient api; @override State<LoginPage> createState() => _LoginPageState(); }
class _LoginPageState extends State<LoginPage> {
  final phone = TextEditingController(); final password = TextEditingController(); bool reg = false; bool busy = false;
  Future<void> submit() async {
    final value = phone.text.trim().replaceAll(' ', '');
    if (!RegExp(r'^09\d{9}$').hasMatch(value) || password.text.length < 8) { ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('شماره موبایل معتبر و رمز عبور حداقل ۸ کاراکتر وارد کنید.'))); return; }
    setState(() => busy = true);
    try { if (reg) await widget.api.register(value, password.text); await widget.api.login(value, password.text); if (mounted) Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => Dashboard(api: widget.api))); }
    catch (x) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(x.toString().replaceFirst('Exception: ', '')))); }
    finally { if (mounted) setState(() => busy = false); }
  }
  @override Widget build(BuildContext c) => Directionality(textDirection: TextDirection.rtl, child: Scaffold(body: Center(child: ConstrainedBox(constraints: const BoxConstraints(maxWidth: 430), child: Padding(padding: const EdgeInsets.all(24), child: Card(child: Padding(padding: const EdgeInsets.all(28), child: Column(mainAxisSize: MainAxisSize.min, children: [const Icon(Icons.directions_car_filled_rounded, size: 54, color: Color(0xFF10A7A0)), const SizedBox(height: 12), const Text('دستیار خودرو', style: TextStyle(fontSize: 28, fontWeight: FontWeight.w900)), const SizedBox(height: 6), const Text('مدیریت خودرو، سرویس و هزینه‌ها', style: TextStyle(color: Colors.grey)), const SizedBox(height: 28), TextField(controller: phone, keyboardType: TextInputType.phone, decoration: const InputDecoration(labelText: 'شماره موبایل *', hintText: '09123456789', prefixIcon: Icon(Icons.phone_android_outlined), border: OutlineInputBorder())), const SizedBox(height: 12), TextField(controller: password, obscureText: true, decoration: const InputDecoration(labelText: 'رمز عبور *', hintText: 'حداقل ۸ کاراکتر', prefixIcon: Icon(Icons.lock_outline), border: OutlineInputBorder())), const SizedBox(height: 18), SizedBox(width: double.infinity, height: 50, child: FilledButton(onPressed: busy ? null : submit, child: Text(busy ? 'در حال اتصال...' : reg ? 'ساخت حساب' : 'ورود'))), TextButton(onPressed: busy ? null : () => setState(() => reg = !reg), child: Text(reg ? 'حساب دارم؛ ورود' : 'حساب ندارم؛ ثبت‌نام'))]))))))));
}

class Dashboard extends StatefulWidget { const Dashboard({super.key, required this.api}); final ApiClient api; @override State<Dashboard> createState() => _DashboardState(); }
class _DashboardState extends State<Dashboard> { List<Map<String, dynamic>> cars = []; bool loading = true; String? err; @override void initState(){super.initState();load();} Future<void> load() async {try{final d=await widget.api.vehicles();if(mounted)setState(()=>cars=d);}catch(x){if(mounted)setState(()=>err=x.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(()=>loading=false);}} Future<void> add() async {final car=await showDialog<Map<String,dynamic>>(context:context,builder:(_)=>AddVehicle(api:widget.api));if(car!=null&&mounted){setState(()=>cars.insert(0,car));ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('خودرو با موفقیت ثبت شد.')));}} @override Widget build(BuildContext c){return Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:const Text('دستیار خودرو',style:TextStyle(fontWeight:FontWeight.w900)),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh_rounded))]),body:LayoutBuilder(builder:(c,x){final wide=x.maxWidth>=760;return Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:1080),child:ListView(padding:const EdgeInsets.all(20),children:[Container(padding:const EdgeInsets.all(24),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xFF172B4D),Color(0xFF244A73)]),borderRadius:BorderRadius.circular(24)),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('همه‌چیز درباره خودروی شما، یک‌جا',style:TextStyle(color:Colors.white70)),SizedBox(height:8),Text('خودرویت را بهتر بشناس',style:TextStyle(color:Colors.white,fontSize:26,fontWeight:FontWeight.w900)),SizedBox(height:8),Text('سرویس‌ها، هزینه‌ها و یادآوری‌ها را مدیریت کن.',style:TextStyle(color:Colors.white70))])),const SizedBox(height:22),Row(children:[const Expanded(child:Text('خودروهای من',style:TextStyle(fontSize:20,fontWeight:FontWeight.w900))),FilledButton.icon(onPressed:add,icon:const Icon(Icons.add),label:const Text('افزودن خودرو'))]),const SizedBox(height:12),if(loading)const Padding(padding:EdgeInsets.all(35),child:Center(child:CircularProgressIndicator()))else if(err!=null)Card(child:Padding(padding:const EdgeInsets.all(20),child:Text('خطا: $err')))else if(cars.isEmpty)Card(child:Padding(padding:const EdgeInsets.all(28),child:Column(children:[const Icon(Icons.directions_car_outlined,size:55,color:Colors.grey),const SizedBox(height:12),const Text('هنوز خودرویی ثبت نکرده‌ای.'),const SizedBox(height:12),FilledButton.icon(onPressed:add,icon:const Icon(Icons.add),label:const Text('اولین خودرو را ثبت کن'))])))else GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:wide?2:1,mainAxisSpacing:12,crossAxisSpacing:12,childAspectRatio:wide?2.5:2.8,children:cars.map((v)=>CarCard(car:v)).toList()),const SizedBox(height:24),const Text('دسترسی سریع',style:TextStyle(fontSize:19,fontWeight:FontWeight.w900)),const SizedBox(height:12),GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:wide?4:2,mainAxisSpacing:12,crossAxisSpacing:12,childAspectRatio:1.25,children:const[ActionCard(icon:Icons.history,title:'سوابق سرویس',sub:'تعمیرات و نگهداری'),ActionCard(icon:Icons.receipt_long,title:'هزینه‌ها',sub:'مدیریت مخارج'),ActionCard(icon:Icons.notifications_active_outlined,title:'یادآورها',sub:'سرویس و بیمه'),ActionCard(icon:Icons.smart_toy_outlined,title:'دستیار هوشمند',sub:'راهنمای اولیه خودرو')])])));}) );}}

