class AddVehicle extends StatefulWidget { const AddVehicle({super.key,required this.api}); final ApiClient api; @override State<AddVehicle> createState()=>_AddVehicleState(); }
class _AddVehicleState extends State<AddVehicle> { final n=TextEditingController();final m=TextEditingController();final mo=TextEditingController();final y=TextEditingController();final o=TextEditingController();String fuel='petrol';bool busy=false;Future<void> save()async{if(m.text.isEmpty||mo.text.isEmpty||o.text.isEmpty)return;final odometer=int.tryParse(o.text);if(odometer==null||odometer<0)return;setState(()=>busy=true);try{final v=await widget.api.addVehicle(nickname:n.text.isEmpty?'خودروی من':n.text,make:m.text,model:mo.text,year:int.tryParse(y.text)??0,odometer:odometer,fuelType:fuel);if(mounted)Navigator.pop(context,v);}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(x.toString().replaceFirst('Exception: ',''))));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>AlertDialog(title:const Text('افزودن خودرو'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'نام خودرو')),const SizedBox(height:10),TextField(controller:m,decoration:const InputDecoration(labelText:'برند *')),const SizedBox(height:10),TextField(controller:mo,decoration:const InputDecoration(labelText:'مدل *')),const SizedBox(height:10),TextField(controller:y,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'سال')),const SizedBox(height:10),TextField(controller:o,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'کیلومتر فعلی *')),const SizedBox(height:10),DropdownButtonFormField<String>(initialValue:fuel,items:const[DropdownMenuItem(value:'petrol',child:Text('بنزین')),DropdownMenuItem(value:'diesel',child:Text('گازوئیل')),DropdownMenuItem(value:'hybrid',child:Text('هیبرید')),DropdownMenuItem(value:'electric',child:Text('برقی')),DropdownMenuItem(value:'lpg',child:Text('گاز مایع')),DropdownMenuItem(value:'cng',child:Text('گاز طبیعی')),DropdownMenuItem(value:'other',child:Text('سایر'))],onChanged:(v)=>setState(()=>fuel=v??'petrol'))]),actions:[TextButton(onPressed:busy?null:()=>Navigator.pop(context),child:const Text('انصراف')),FilledButton(onPressed:busy?null:save,child:Text(busy?'در حال ثبت...':'ثبت خودرو'))]); }
